// src/layouts/ledger/data/ledgerTableData.js
import MDTypography from "components/MDTypography";

const fmtINR = (n) =>
  Number(n ?? 0).toLocaleString("en-IN", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

export default function ledgerTableData(items) {
  // ✅ Normalize here too, just in case
  const list = Array.isArray(items) ? items : items?.results ?? items?.data ?? [];

  const columns = [
    // { Header: "ID", accessor: "id", align: "left" },
    { Header: "Type", accessor: "entry_type", align: "center" },
    { Header: "Amount", accessor: "amount", align: "center" },
    { Header: "Month", accessor: "month", align: "center" },
    { Header: "Year", accessor: "year", align: "center" },
    { Header: "Category", accessor: "category", align: "center" },
    // { Header: "Method", accessor: "payment_method", align: "center" },
    { Header: "Note", accessor: "note", align: "left" },
    { Header: "Date", accessor: "date", align: "center" },
  ];

  const rows = list.map((it) => {
    const isCredit = it.entry_type?.toLowerCase() === "credit";
    const color = isCredit ? "success" : "error";

    return {
      id: it.id,
      entry_type: (
        <MDTypography variant="button" color={color}>
          {it.entry_type}
        </MDTypography>
      ),
      amount: (
        <MDTypography variant="button" color={color}>
          ₹{fmtINR(it.amount)}
        </MDTypography>
      ),
      month: it.month || "—",
      year: it.year ?? "—",
      category: it.category || "—",
      payment_method: it.payment_method || "—",
      note: it.note || "—",
      date: it.date,
    };
  });

  return { columns, rows };
}
