import { useEffect, useState } from "react";
import axios from "axios";
import Grid from "@mui/material/Grid";
import Card from "@mui/material/Card";
import TextField from "@mui/material/TextField";
import MenuItem from "@mui/material/MenuItem";
import IconButton from "@mui/material/IconButton";
import PictureAsPdfIcon from "@mui/icons-material/PictureAsPdf";

import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

import MDBox from "components/MDBox";
import MDTypography from "components/MDTypography";
import DashboardLayout from "examples/LayoutContainers/DashboardLayout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import Footer from "examples/Footer";
import DataTable from "examples/Tables/DataTable";

import maintenanceTableData from "./maintenanceTableData";

import { maintenancetapi } from "../../apis";

function Maintenancetables() {
  // ✅ Get current month & year
  const currentDate = new Date();
  const currentMonth = currentDate.toLocaleString("default", { month: "long" }); // e.g. "August"
  const currentYear = currentDate.getFullYear(); // e.g. 2025

  const [data, setData] = useState([]);
  const [filters, setFilters] = useState({
    year: currentYear,
    month: currentMonth,
    username: "",
  });

  const fetchData = async () => {
    const params = {};
    if (filters.year) params.year = filters.year;
    if (filters.month) params.month = filters.month;
    if (filters.username) params.username = filters.username;

    try {
      const res = await axios.get(maintenancetapi, { params });
      setData(res.data);
    } catch (err) {
      console.error("Error fetching data:", err);
    }
  };

  useEffect(() => {
    fetchData();
  }, [filters]);

  const { columns, rows } = maintenanceTableData(data);

  const months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];

  // ✅ Format currency with comma and 2 decimal places, remove ₹ symbol
  const formatCurrency = (num) => {
    const number = Number(num) || 0;
    const formatted = new Intl.NumberFormat("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(number);

    return formatted.endsWith(".00")
      ? formatted.replace(".00", "")
      : formatted.replace(/[₹]/g, "").trim();
  };

  // ✅ Extract text safely from table cells
  const extractTextFromValue = (value) => {
    if (value === null || value === undefined) return "";
    if (typeof value === "number") return formatCurrency(value);
    if (typeof value === "string") return formatCurrency(value);

    if (value?.props?.children !== undefined) {
      const children = value.props.children;
      if (Array.isArray(children)) {
        return children
          .map((child) =>
            typeof child === "string" || typeof child === "number"
              ? child
              : extractTextFromValue(child)
          )
          .join(" ");
      }
      return extractTextFromValue(children);
    }

    if (typeof value === "object" && value.value) return String(value.value);

    return String(value);
  };

  // ✅ Export to PDF with "Due" column highlighted in red
  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.text("Maintenance Payments", 14, 15);

    const tableColumn = columns.map((col) => col.Header);
    const dueIndex = columns.findIndex((col) => col.Header.toLowerCase().includes("due"));

    const tableBody = rows.map((row) =>
      columns.map((col) => extractTextFromValue(row[col.accessor]))
    );

    autoTable(doc, {
      startY: 20,
      head: [tableColumn],
      body: tableBody,
      styles: { fontSize: 9 },
      headStyles: { fillColor: [41, 128, 185], textColor: 255 },
      didParseCell: (data) => {
        if (
          data.section === "body" &&
          data.column.index === dueIndex &&
          data.cell.text &&
          data.cell.text.length > 0 &&
          data.cell.text[0] !== "0"
        ) {
          data.cell.styles.textColor = [255, 0, 0]; // highlight due in red
        }
      },
    });

    doc.save("maintenance_payments.pdf");
  };

  return (
    <DashboardLayout>
      <DashboardNavbar />
      <MDBox pt={6} pb={3}>
        <Grid container spacing={2} mb={2}>
          <Grid item xs={12} sm={4}>
            <TextField
              label="Filter by Username"
              fullWidth
              value={filters.username}
              onChange={(e) => setFilters({ ...filters, username: e.target.value })}
            />
          </Grid>

          {/* ✅ Month Dropdown with Default Current Month */}
          <Grid item xs={12} sm={4}>
            <TextField
              label="Filter by Month"
              select
              fullWidth
              value={filters.month}
              onChange={(e) => setFilters({ ...filters, month: e.target.value })}
            >
              <MenuItem value="">All</MenuItem>
              {months.map((m) => (
                <MenuItem key={m} value={m}>
                  {m}
                </MenuItem>
              ))}
            </TextField>
          </Grid>

          {/* ✅ Year Dropdown with Default Current Year */}
          <Grid item xs={12} sm={4}>
            <TextField
              label="Filter by Year"
              type="number"
              fullWidth
              value={filters.year}
              onChange={(e) => setFilters({ ...filters, year: e.target.value })}
            />
          </Grid>
        </Grid>

        <Grid container spacing={6}>
          <Grid item xs={12}>
            <Card>
              <MDBox
                mx={2}
                mt={-3}
                py={3}
                px={2}
                display="flex"
                justifyContent="space-between"
                alignItems="center"
                variant="gradient"
                bgColor="info"
                borderRadius="lg"
                coloredShadow="info"
              >
                <MDTypography variant="h6" color="white">
                  Maintenance Payments
                </MDTypography>
                <IconButton onClick={handleExportPDF} color="inherit" title="Export as PDF">
                  <PictureAsPdfIcon style={{ color: "white" }} />
                </IconButton>
              </MDBox>
              <MDBox pt={3}>
                <DataTable
                  table={{ columns, rows }}
                  isSorted={false}
                  entriesPerPage
                  showTotalEntries
                  noEndBorder
                />
              </MDBox>
            </Card>
          </Grid>
        </Grid>
      </MDBox>
      <Footer />
    </DashboardLayout>
  );
}

export default Maintenancetables;
