// src/layouts/ledger/index.js
import { useEffect, useState } from "react";
import axios from "axios";
import Grid from "@mui/material/Grid";
import Card from "@mui/material/Card";
import TextField from "@mui/material/TextField";
import MenuItem from "@mui/material/MenuItem";

import MDBox from "components/MDBox";
import MDTypography from "components/MDTypography";
import DashboardLayout from "examples/LayoutContainers/DashboardLayout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import Footer from "examples/Footer";
import DataTable from "examples/Tables/DataTable";

import ledgerTableData from "./ledgerTableData";
import { ledgerEntriesApi } from "../../apis"; // adjust path if needed

function LedgerTable() {
  // ✅ Get current month & year
  const currentDate = new Date();
  const currentMonth = currentDate.toLocaleString("default", { month: "long" }); // "August"
  const currentYear = currentDate.getFullYear(); // 2025

  const [data, setData] = useState([]);
  const [filters, setFilters] = useState({
    entry_type: "",
    month: currentMonth, // ✅ default month
    year: currentYear, // ✅ default year
  });

  const fetchData = async () => {
    const params = {};
    if (filters.entry_type) params.entry_type = filters.entry_type;
    if (filters.month) params.month = filters.month;
    if (filters.year) params.year = filters.year;

    try {
      const res = await axios.get(ledgerEntriesApi, { params });
      setData(res.data);
    } catch (err) {
      console.error("Error fetching ledger entries:", err);
    }
  };

  useEffect(() => {
    fetchData();
  }, [filters]);

  const { columns, rows } = ledgerTableData(data);

  const months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];

  return (
    <DashboardLayout>
      <DashboardNavbar />
      <MDBox pt={6} pb={3}>
        <Grid container spacing={2} mb={2}>
          <Grid item xs={12} sm={4}>
            <TextField
              label="Type"
              select
              fullWidth
              value={filters.entry_type}
              onChange={(e) => setFilters({ ...filters, entry_type: e.target.value })}
            >
              <MenuItem value="">All</MenuItem>
              <MenuItem value="credit">Credit</MenuItem>
              <MenuItem value="debit">Debit</MenuItem>
            </TextField>
          </Grid>

          {/* ✅ Month Dropdown with current month preselected */}
          <Grid item xs={12} sm={4}>
            <TextField
              label="Month"
              select
              fullWidth
              value={filters.month}
              onChange={(e) => setFilters({ ...filters, month: e.target.value })}
            >
              <MenuItem value="">All</MenuItem>
              {months.map((m) => (
                <MenuItem key={m} value={m}>
                  {m}
                </MenuItem>
              ))}
            </TextField>
          </Grid>

          {/* ✅ Year Input with current year preselected */}
          <Grid item xs={12} sm={4}>
            <TextField
              label="Year"
              type="number"
              fullWidth
              value={filters.year}
              onChange={(e) => setFilters({ ...filters, year: e.target.value })}
            />
          </Grid>
        </Grid>
        <br />

        <Grid container spacing={6}>
          <Grid item xs={12}>
            <Card>
              <MDBox
                mx={2}
                mt={-3}
                py={3}
                px={2}
                variant="gradient"
                bgColor="info"
                borderRadius="lg"
                coloredShadow="info"
              >
                <MDTypography variant="h6" color="white">
                  Ledger entries
                </MDTypography>
              </MDBox>
              <MDBox pt={3}>
                <DataTable
                  table={{ columns, rows }}
                  isSorted={false}
                  entriesPerPage
                  showTotalEntries
                  noEndBorder
                />
              </MDBox>
            </Card>
          </Grid>
        </Grid>
      </MDBox>
      <Footer />
    </DashboardLayout>
  );
}

export default LedgerTable;
